package com.a11y.a11y_ai_readiness.agent;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.List;

/**
 * One run's worth of metrics, written verbatim to results/*.json so that every number reported
 * anywhere is generated by an actual run rather than typed by hand.
 */
public record AgentRunResult(
        String variant,
        String provider,
        String model,
        Instant startedAt,
        Instant finishedAt,
        boolean success,
        String confirmationCode,
        int toolCalls,
        int maxToolCalls,
        // True if the cap cut the run off: spoiled data, exclude it from aggregates.
        boolean budgetExhausted,
        long promptTokens,
        long completionTokens,
        long totalTokens,
        BigDecimal estimatedCostUsd,
        int finalSnapshotChars,
        String finalModelMessage,
        List<String> actionLog
) {
}
